const r = await tools.exec_command({cmd:"python - <<'PY'
import numpy as np,json
# compare spectral grids global for max amplitudes random
rat=np.array([1.,4.,1.]); z=np.array([1.,1.,-1.])
def p(e,n):
 x=np.arange(n)*2*np.pi/n;m=np.fft.fftfreq(n,1/n)
 c=np.array([e['means'][i]+e['amplitudes'][i]*np.cos(e['waves'][i]*x+e['phases'][i]) for i in [0,1]])
 c=np.vstack((c,c.sum(0)));g=np.fft.ifft(1j*m*np.fft.fft(c,axis=1),axis=1).real
 K=rat@c;A=(rat*z)@g; q=A/K; I=-np.mean(q)/np.mean(1/K);E=q+I/K
 f=-rat[:,None]*g+(rat*z)[:,None]*c*E
 dc=-np.fft.ifft(1j*m*np.fft.fft(f,axis=1),axis=1).real
 return 2*np.mean(dc[e['species']]*np.cos(e['detector']*x+e['detector_phase']))
rng=np.random.default_rng(2)
for k in range(10):
 means=rng.uniform(.6,1.4,2); amps=rng.uniform(-.85,.85,2)*means; waves=rng.integers(1,3,2); phases=rng.uniform(-np.pi,np.pi,2)
 e={'means':means.tolist(),'amplitudes':amps.tolist(),'waves':waves.tolist(),'phases':phases.tolist(),'species':int(rng.integers(3)),'detector':int(rng.integers(1,5)),'detector_phase':rng.uniform(-np.pi,np.pi)}
 a=p(e,257);b=p(e,4096)
 print(abs(a-b),a,b)
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:10000});
